files.apply.sql:
set local statement_timeout = '60min';
set local lock_timeout = '15s';

-- 0. preflight: every column this script writes exists and is text; ids are uuid; slug and updated_at exist
do $pre$
declare v_missing text;
begin
  select string_agg(n.t || '.' || n.c, ', ') into v_missing
  from (values
    ($seo$blog_posts$seo$, $seo$content$seo$),
    ($seo$content_pages$seo$, $seo$body_markdown$seo$),
    ($seo$content_pages$seo$, $seo$content$seo$),
    ($seo$content_pages$seo$, $seo$description$seo$),
    ($seo$content_pages$seo$, $seo$og_description$seo$),
    ($seo$content_pages$seo$, $seo$seo_description$seo$),
    ($seo$content_pages$seo$, $seo$seo_title$seo$)) n(t, c)
  where not exists (select 1 from information_schema.columns ic
                    where ic.table_schema = 'public' and ic.table_name = n.t and ic.column_name = n.c
                      and ic.data_type in ('text', 'character varying'));
  if v_missing is not null then
    raise exception 'SEO repair preflight: these columns are missing or not text: %', v_missing;
  end if;
  select string_agg(n.t || '.id / .slug / .updated_at', ', ') into v_missing
  from (values
    ($seo$blog_posts$seo$, 'id'),
    ($seo$content_pages$seo$, 'id')) n(t, c)
  where not exists (select 1 from information_schema.columns ic
                    where ic.table_schema = 'public' and ic.table_name = n.t and ic.column_name = 'id' and ic.data_type = 'uuid')
     or not exists (select 1 from information_schema.columns ic
                    where ic.table_schema = 'public' and ic.table_name = n.t and ic.column_name = 'slug')
     or not exists (select 1 from information_schema.columns ic
                    where ic.table_schema = 'public' and ic.table_name = n.t and ic.column_name = 'updated_at'
                      and ic.data_type like 'timestamp%');
  if v_missing is not null then
    raise exception 'SEO repair preflight: id is not uuid, or slug / updated_at missing: %', v_missing;
  end if;
end
$pre$;

-- 1. backup and log tables (created once; never dropped or truncated by this script)
create table if not exists seo_repair.seo_repair_backup_20261115 (
  table_name     text not null,
  row_id         text not null,
  column_name    text not null,
  old_value      text not null,
  old_md5        text not null,
  old_updated_at timestamptz,
  taken_at       timestamptz not null default now(),
  run_id         text not null,
  primary key (table_name, row_id, column_name, old_md5)
);
comment on table seo_repair.seo_repair_backup_20261115 is
  'SEO repair 2026-11 (F5/F14): full value of every field before apply.sql first changed it, and the row''s updated_at at that moment. Never overwritten.';
create table if not exists seo_repair.seo_repair_change_log (
  id             bigserial primary key,
  run_id         text not null,
  rule_id        text not null,
  table_name     text not null,
  row_id         text not null,
  slug           text,
  column_name    text not null,
  old_md5        text not null,
  new_md5        text not null,
  occurrences    integer not null,
  applied_at     timestamptz not null default now(),
  rolled_back_at timestamptz
);
create index if not exists seo_repair_change_log_field_idx
  on seo_repair.seo_repair_change_log (table_name, row_id, column_name);
create table if not exists seo_repair.seo_repair_skip_log (
  id          bigserial primary key,
  run_id      text not null,
  rule_id     text not null,
  table_name  text not null,
  row_id      text not null,
  slug        text,
  column_name text not null,
  reason      text not null,
  logged_at   timestamptz not null default now()
);
create table if not exists seo_repair.seo_repair_rollback_log (
  id           bigserial primary key,
  rollback_run text not null,
  table_name   text not null,
  row_id       text not null,
  slug         text,
  column_name  text not null,
  status       text not null,
  reason       text,
  logged_at    timestamptz not null default now()
);
-- Not readable or writable through the public API (same convention as the 2026-05 backup tables).
alter table seo_repair.seo_repair_backup_20261115 enable row level security;
alter table seo_repair.seo_repair_change_log enable row level security;
alter table seo_repair.seo_repair_skip_log enable row level security;
alter table seo_repair.seo_repair_rollback_log enable row level security;
do $grants$
declare r text; t text;
begin
  foreach t in array array['seo_repair_backup_20261115', 'seo_repair_change_log', 'seo_repair_skip_log',
                           'seo_repair_rollback_log'] loop
    foreach r in array array['anon', 'authenticated'] loop
      if exists (select 1 from pg_roles where rolname = r) then
        execute format('revoke all on seo_repair.%I from %I', t, r);
      end if;
    end loop;
  end loop;
end
$grants$;

-- 2. this run
create temp table _seo_run on commit drop as
select 'apply-' || to_char(now() at time zone 'utc', 'YYYYMMDD"T"HH24MISS"Z"') || '-' || txid_current()::text as run_id;
create temp table _seo_run_stats (fields_changed int, fields_already_applied int, fields_skipped_by_pin int) on commit drop;

-- 3. rules and field md5 pins: copied from the stage tables, after checking they are the reviewed ones
do $chk$
declare v_pins text := (select coalesce(encode(sha256(convert_to(string_agg(t || E'\t' || rid || E'\t' || col || E'\t' || md5 || E'\n', '' order by t collate "C", rid collate "C", col collate "C"), 'UTF8')), 'hex'), encode(sha256(''::bytea), 'hex')) from seo_repair.stage_pins);
begin
  if (select coalesce(encode(sha256(convert_to(string_agg(concat_ws('|', case when rule_id is null then '~' else length(rule_id::text)::text || ':' || rule_id::text end, case when form is null then '~' else length(form::text)::text || ':' || form::text end, case when path is null then '~' else length(path::text)::text || ':' || path::text end, case when action is null then '~' else length(action::text)::text || ':' || action::text end, case when old_target is null then '~' else length(old_target::text)::text || ':' || old_target::text end, case when dest is null then '~' else length(dest::text)::text || ':' || dest::text end, case when exp_present is null then '~' else length(exp_present::text)::text || ':' || exp_present::text end, case when exp_ins is null then '~' else length(exp_ins::text)::text || ':' || exp_ins::text end, case when exp_change is null then '~' else length(exp_change::text)::text || ':' || exp_change::text end, case when tol is null then '~' else length(tol::text)::text || ':' || tol::text end, case when pat_ctx is null then '~' else length(pat_ctx::text)::text || ':' || pat_ctx::text end, case when repl_ctx is null then '~' else length(repl_ctx::text)::text || ':' || repl_ctx::text end, case when pat_md is null then '~' else length(pat_md::text)::text || ':' || pat_md::text end, case when pat_html is null then '~' else length(pat_html::text)::text || ':' || pat_html::text end) || E'\n', '' order by rule_id collate "C"), 'UTF8')), 'hex'), encode(sha256(''::bytea), 'hex')) from seo_repair.stage_link_rules) <> 'ea56d812b647b1809f19940515ff6c2c24c95cbe0ad57d4413c62d55750cd4e5' or (select coalesce(encode(sha256(convert_to(string_agg(concat_ws('|', case when rule_id is null then '~' else length(rule_id::text)::text || ':' || rule_id::text end, case when t is null then '~' else length(t::text)::text || ':' || t::text end, case when rid is null then '~' else length(rid::text)::text || ':' || rid::text end, case when slug is null then '~' else length(slug::text)::text || ':' || slug::text end, case when col is null then '~' else length(col::text)::text || ':' || col::text end, case when ord is null then '~' else length(ord::text)::text || ':' || ord::text end, case when category is null then '~' else length(category::text)::text || ':' || category::text end, case when old_text is null then '~' else length(old_text::text)::text || ':' || old_text::text end, case when old_md5 is null then '~' else length(old_md5::text)::text || ':' || old_md5::text end, case when new_text is null then '~' else length(new_text::text)::text || ':' || new_text::text end) || E'\n', '' order by rule_id collate "C"), 'UTF8')), 'hex'), encode(sha256(''::bytea), 'hex')) from seo_repair.stage_fee_rules) <> '4cca7d1a3f3164326eccd218318e54e73388ba80353aa91857f9abc2a3bb9cb3' then
    raise exception 'SEO repair: the staged rules are not the rules of this bundle; nothing changed';
  end if;
  if v_pins is distinct from (select v from seo_repair.stage_meta where k = 'pin_set_sha256') then
    raise exception 'SEO repair: the staged pins changed after the pin read; nothing changed';
  end if;
  if v_pins is distinct from (select v from seo_repair.stage_meta where k = 'reviewed_pin_set_sha256') then
    raise exception 'SEO repair: pin set % has not been marked reviewed (seo_repair.stage_meta reviewed_pin_set_sha256); nothing changed', v_pins;
  end if;
end
$chk$;
create temp table _seo_link_rules (rule_id text primary key, form text, path text, action text, old_target text,
  dest text, exp_present int, exp_ins int, exp_change int, tol int, pat_ctx text, repl_ctx text, pat_md text,
  pat_html text) on commit drop;
insert into _seo_link_rules (rule_id, form, path, action, old_target, dest, exp_present, exp_ins, exp_change, tol, pat_ctx, repl_ctx, pat_md, pat_html) select rule_id, form, path, action, old_target, dest, exp_present, exp_ins, exp_change, tol, pat_ctx, repl_ctx, pat_md, pat_html from seo_repair.stage_link_rules;
create temp table _seo_fee_rules (rule_id text primary key, t text, rid text, slug text, col text, ord int,
  category text, old_text text, old_md5 text, new_text text, pin text) on commit drop;
insert into _seo_fee_rules (rule_id, t, rid, slug, col, ord, category, old_text, old_md5, new_text, pin) select rule_id, t, rid, slug, col, ord, category, old_text, old_md5, new_text, pin from seo_repair.stage_fee_rules;
create temp table _seo_pins (t text, rid text, col text, md5 text, primary key (t, rid, col)) on commit drop;
insert into _seo_pins (t, rid, col, md5) select t, rid, col, md5 from seo_repair.stage_pins;

-- 4. evaluation against the live data (the same queries as dry-run.sql)
create temp table _seo_link_eval on commit drop as
select r.rule_id, k.t, k.rid, k.slug, k.col, md5(k.val) as cur_md5, pn.md5 as pin,
  (select count(*) from regexp_matches(k.val, r.pat_ctx, 'g'))::int as present,
  (case when r.action = 'REWRITE' then (select count(*) from regexp_matches(k.val, r.pat_ctx, 'g'))
        else (select count(*) from regexp_matches(k.val, r.pat_md, 'g'))
           + (select count(*) from regexp_matches(k.val, r.pat_html, 'g')) end)::int as handled,
  exists (select 1 from regexp_split_to_table(k.val, $seo$\n|<(?:/?(?:[Pp]|[Ll][Ii]|[Uu][Ll]|[Oo][Ll]|[Hh][1-6]|[Dd][Ii][Vv]|[Tt][RrDdHh]|[Tt][Aa][Bb][Ll][Ee]|[Bb][Ll][Oo][Cc][Kk][Qq][Uu][Oo][Tt][Ee]|[Ss][Ee][Cc][Tt][Ii][Oo][Nn]|[Dd][DdTt])\M[^>]*|[Bb][Rr]\s*/?)>$seo$) b
          where b ~ r.pat_ctx and b ~* $seo$insur|liabil|coverage|\mcovered\M|claim|damage|waiver|injur|indemn|\mseguros?\M|responsabilidad|cobertura|reclam|\mdaños?\M|lesi[oó]n$seo$) as ins
from (
  select f.t, f.rid, f.slug, f.col, f.val, n.form, n.path
  from (
    select $seo$content_pages$seo$::text as t, x.id::text as rid, x.slug, $seo$content$seo$::text as col, x.content as val
    from public.content_pages x where x.content ~* $seo$poolrentalnearme|\]\(\s*<?/|href$seo$
    union all
    select $seo$content_pages$seo$::text as t, x.id::text as rid, x.slug, $seo$body_markdown$seo$::text as col, x.body_markdown as val
    from public.content_pages x where x.body_markdown ~* $seo$poolrentalnearme|\]\(\s*<?/|href$seo$
    union all
    select $seo$blog_posts$seo$::text as t, x.id::text as rid, x.slug, $seo$content$seo$::text as col, x.content as val
    from public.blog_posts x where x.content ~* $seo$poolrentalnearme|\]\(\s*<?/|href$seo$
  ) f
  cross join lateral (
    select distinct
      case when m[1] ~* '^https?://poolrentalnearme\.com' then 'n' else 'w' end as form,
      coalesce(nullif(regexp_replace(split_part(split_part(
        regexp_replace(m[1], '^https?://(www\.)?poolrentalnearme\.com', '', 'i'), '#', 1), '?', 1), '/+$', ''), ''), '/') as path
    from regexp_matches(f.val, $seo$(?:\]\(\s*<?|[Hh][Rr][Ee][Ff]\s*=\s*\\?["'])([^)\s"'<>\\]+)$seo$, 'g') m
    where m[1] ~* '^https?://(www\.)?poolrentalnearme\.com' or (m[1] ~ '^/' and m[1] !~ '^//')
  ) n
) k
join _seo_link_rules r on r.form = k.form and r.path = k.path
left join _seo_pins pn on pn.t = k.t and pn.rid = k.rid and pn.col = k.col;
create temp table _seo_fee_eval on commit drop as
select r.rule_id, r.t, r.rid, r.slug, r.col, r.ord, r.old_md5, r.pin,
  md5(r.old_text) = r.old_md5 as lit_ok,
  coalesce(v.row_found, false) as row_found,
  v.val is not null as has_val,
  md5(v.val) as cur_md5,
  coalesce((length(v.val) - length(replace(v.val, r.old_text, ''))) / length(r.old_text), 0) as occ
from _seo_fee_rules r
left join lateral (
    select true as row_found, (case r.col when $seo$body_markdown$seo$ then x.body_markdown when $seo$content$seo$ then x.content when $seo$description$seo$ then x.description when $seo$og_description$seo$ then x.og_description when $seo$seo_description$seo$ then x.seo_description when $seo$seo_title$seo$ then x.seo_title end)::text as val
    from public.content_pages x where r.t = $seo$content_pages$seo$ and x.id = r.rid::uuid
) v on true;
create temp table _seo_prior on commit drop as
select rule_id, count(*)::int as n
from (select distinct rule_id, table_name, row_id, column_name
      from seo_repair.seo_repair_change_log where rolled_back_at is null) d
group by rule_id;

-- 5. count guard, field guard, backup, apply, log
do $apply$
declare
  v_run      text := (select run_id from _seo_run);
  v_bad      text[] := '{}';
  v_nbad     int := 0;
  rec        record;
  fld        record;
  fr         record;
  lr         record;
  v_val      text;
  v_orig     text;
  v_new      text;
  v_slug     text;
  v_upd      timestamptz;
  v_row_upd  timestamptz;
  v_row_key  text := '';
  v_pin      text;
  v_last     text;
  v_n        int;
  v_left     int;
  v_rows     int;
  v_total    int;
  v_would    int;
  v_prior    int;
  v_tol      int;
  v_fields   int := 0;
  v_done     int := 0;
  v_skipf    int := 0;
begin
  -- guard 1: every embedded fee anchor arrived byte-exact
  if exists (select 1 from _seo_fee_eval where not lit_ok) then
    raise exception 'SEO repair: a fee old_text literal does not match its md5 (file damaged in transit); nothing changed';
  end if;
  -- guard 2: the field md5 pins (PENDING-READS P1) must be in this script
  select count(*) into v_n from _seo_fee_rules where pin is null;
  if v_n > 0 or not exists (select 1 from _seo_pins) then
    raise exception 'SEO repair: % fee rule(s) have no field md5 pin and % pins are loaded; run PENDING-READS P1, regenerate with --pins, re-run the tests. Nothing changed',
      v_n, (select count(*) from _seo_pins);
  end if;
  -- guard 3: per link rule, fields holding the target now (pin-matching ones it would change + insurance-skipped)
  -- plus fields an earlier run already changed, against the snapshot count
  for rec in
    select r.rule_id, r.old_target, r.exp_present, r.tol,
           (select count(*) from _seo_link_eval e where e.rule_id = r.rule_id and e.handled > 0 and not e.ins
              and e.pin = e.cur_md5)::int as would,
           (select count(*) from _seo_link_eval e where e.rule_id = r.rule_id and e.ins)::int as ins,
           coalesce((select p.n from _seo_prior p where p.rule_id = r.rule_id), 0)::int as prior
    from _seo_link_rules r order by r.rule_id
  loop
    if abs(rec.would + rec.ins + rec.prior - rec.exp_present) > rec.tol then
      v_nbad := v_nbad + 1;
      raise notice 'COUNT GUARD %: % expected % (tolerance %), found % to change + % insurance-skipped + % already applied',
        rec.rule_id, rec.old_target, rec.exp_present, rec.tol, rec.would, rec.ins, rec.prior;
      if v_nbad <= 25 then
        v_bad := v_bad || format('%s expected %s found %s+%s+%s', rec.rule_id, rec.exp_present, rec.would, rec.ins, rec.prior);
      end if;
    end if;
  end loop;
  -- guard 4: fee rules together (each is one field; a field edited since the pin is skipped, not overwritten)
  select count(*) into v_total from _seo_fee_rules;
  select count(*) into v_would from _seo_fee_eval where lit_ok and has_val and occ = 1 and cur_md5 = pin;
  select count(*) into v_prior from _seo_prior p join _seo_fee_rules r using (rule_id);
  v_tol := 2 + floor(v_total * 0.02)::int;
  if abs(v_would + v_prior - v_total) > v_tol then
    v_nbad := v_nbad + 1;
    v_bad := v_bad || format('fee rules expected %s found %s+%s (tolerance %s)', v_total, v_would, v_prior, v_tol);
  end if;
  raise notice 'count guard: fee rules expected %, would change %, already applied %, tolerance %',
    v_total, v_would, v_prior, v_tol;
  if v_nbad > 0 then
    raise exception 'SEO repair aborted by the count guard (% rule group(s) out of tolerance; the script is stale or the data moved): %',
      v_nbad, array_to_string(v_bad, '; ');
  end if;

  -- apply, one field at a time, under a row lock
  for fld in
    select t, rid, col from (
      select t, rid, col from _seo_fee_rules
      union
      select t, rid, col from _seo_link_eval
    ) x order by t, rid, col
  loop
    execute format('select %I, slug, updated_at from public.%I where id = $1::uuid for update', fld.col, fld.t)
      into v_val, v_slug, v_upd using fld.rid;
    get diagnostics v_rows = row_count;  -- EXECUTE does not set FOUND
    if v_rows = 0 then
      insert into seo_repair.seo_repair_skip_log (run_id, rule_id, table_name, row_id, slug, column_name, reason)
      select v_run, rule_id, fld.t, fld.rid, null, fld.col, 'row no longer exists'
      from (select rule_id from _seo_fee_rules where t = fld.t and rid = fld.rid and col = fld.col
            union all select rule_id from _seo_link_eval where t = fld.t and rid = fld.rid and col = fld.col) z;
      continue;
    end if;
    v_orig := v_val;
    -- the row's updated_at before this run touched it (fields of one row are consecutive; the trigger bumps it on
    -- the first changed field)
    if v_row_key is distinct from fld.t || '/' || fld.rid then
      v_row_key := fld.t || '/' || fld.rid;
      v_row_upd := v_upd;
    end if;

    -- field guard: the value must be exactly the one the reviewed pin read saw (PENDING-READS P1)
    select md5 into v_pin from _seo_pins where t = fld.t and rid = fld.rid and col = fld.col;
    if v_val is null or v_pin is null or md5(v_val) <> v_pin then
      -- an earlier run of this change wrote the current value: nothing to do, nothing to log
      select c.new_md5 into v_last from seo_repair.seo_repair_change_log c
      where c.table_name = fld.t and c.row_id = fld.rid and c.column_name = fld.col and c.rolled_back_at is null
      order by c.id desc limit 1;
      if v_val is not null and v_last is not null and md5(v_val) = v_last then
        v_done := v_done + 1;
        continue;
      end if;
      insert into seo_repair.seo_repair_skip_log (run_id, rule_id, table_name, row_id, slug, column_name, reason)
      select v_run, rule_id, fld.t, fld.rid, v_slug, fld.col,
             case when v_pin is null then 'field was not in the reviewed pin read (P1); not changed'
                  else 'field changed since the reviewed pin read (P1); not changed' end
      from (select rule_id from _seo_fee_rules where t = fld.t and rid = fld.rid and col = fld.col
            union all select rule_id from _seo_link_eval where t = fld.t and rid = fld.rid and col = fld.col) z;
      v_skipf := v_skipf + 1;
      continue;
    end if;

    -- F14 fee corrections: exact substring, exactly one occurrence
    for fr in select * from _seo_fee_rules where t = fld.t and rid = fld.rid and col = fld.col order by ord loop
      v_n := (length(v_val) - length(replace(v_val, fr.old_text, ''))) / length(fr.old_text);
      if v_n <> 1 then
        insert into seo_repair.seo_repair_skip_log (run_id, rule_id, table_name, row_id, slug, column_name, reason)
        values (v_run, fr.rule_id, fld.t, fld.rid, v_slug, fld.col,
                format('old_text occurs %s times (exactly 1 required); not applied', v_n));
        continue;
      end if;
      v_new := replace(v_val, fr.old_text, fr.new_text);
      insert into seo_repair.seo_repair_change_log
        (run_id, rule_id, table_name, row_id, slug, column_name, old_md5, new_md5, occurrences)
      values (v_run, fr.rule_id, fld.t, fld.rid, v_slug, fld.col, md5(v_val), md5(v_new), 1);
      v_val := v_new;
    end loop;

    -- F5 internal links: exact URL boundary, link contexts only
    for lr in
      select e.rule_id, e.ins, r.action, r.pat_ctx, r.repl_ctx, r.pat_md, r.pat_html
      from _seo_link_eval e join _seo_link_rules r using (rule_id)
      where e.t = fld.t and e.rid = fld.rid and e.col = fld.col
      order by e.rule_id
    loop
      if lr.ins then
        insert into seo_repair.seo_repair_skip_log (run_id, rule_id, table_name, row_id, slug, column_name, reason)
        values (v_run, lr.rule_id, fld.t, fld.rid, v_slug, fld.col,
                'link sits in a paragraph or list item mentioning insurance/liability/coverage/claims/damage: not changed, pending Derek');
        continue;
      end if;
      if lr.action = 'REWRITE' then
        v_n := (select count(*) from regexp_matches(v_val, lr.pat_ctx, 'g'));
        v_new := regexp_replace(v_val, lr.pat_ctx, lr.repl_ctx, 'g');
      else
        v_n := (select count(*) from regexp_matches(v_val, lr.pat_md, 'g'))
             + (select count(*) from regexp_matches(v_val, lr.pat_html, 'g'));
        v_new := regexp_replace(regexp_replace(v_val, lr.pat_md, '\1', 'g'), lr.pat_html, '\1', 'g');
      end if;
      v_left := (select count(*) from regexp_matches(v_new, lr.pat_ctx, 'g'));
      if v_left > 0 then
        insert into seo_repair.seo_repair_skip_log (run_id, rule_id, table_name, row_id, slug, column_name, reason)
        values (v_run, lr.rule_id, fld.t, fld.rid, v_slug, fld.col,
                format('%s occurrence(s) in a form this rule does not rewrite (e.g. image or nested link) left unchanged', v_left));
      end if;
      if v_n > 0 and v_new is distinct from v_val then
        insert into seo_repair.seo_repair_change_log
          (run_id, rule_id, table_name, row_id, slug, column_name, old_md5, new_md5, occurrences)
        values (v_run, lr.rule_id, fld.t, fld.rid, v_slug, fld.col, md5(v_val), md5(v_new), v_n);
        v_val := v_new;
      end if;
    end loop;

    if v_val is distinct from v_orig then
      -- backup BEFORE the change; one row per field and old value, never overwritten; keeps the row's updated_at
      insert into seo_repair.seo_repair_backup_20261115 (table_name, row_id, column_name, old_value, old_md5, old_updated_at, run_id)
      values (fld.t, fld.rid, fld.col, v_orig, md5(v_orig), v_row_upd, v_run)
      on conflict (table_name, row_id, column_name, old_md5) do nothing;
      execute format('update public.%I set %I = $1 where id = $2::uuid and md5(%I) = $3', fld.t, fld.col, fld.col)
        using v_val, fld.rid, md5(v_orig);
      get diagnostics v_rows = row_count;
      if v_rows <> 1 then
        raise exception 'SEO repair: guarded update of %.% id % touched % rows; aborting', fld.t, fld.col, fld.rid, v_rows;
      end if;
      v_fields := v_fields + 1;
    end if;
  end loop;
  insert into _seo_run_stats values (v_fields, v_done, v_skipf);
  raise notice 'SEO repair run %: % field(s) changed, % already applied by an earlier run (not logged), % skipped by the field guard',
    v_run, v_fields, v_done, v_skipf;
end
$apply$;

-- 6. remember this run for the summary queries
insert into seo_repair.stage_meta (k, v) values ('last_apply_run', (select run_id from _seo_run))
on conflict (k) do update set v = excluded.v, at = now();

files.loader.sql:
create schema if not exists seo_repair;
revoke all on schema seo_repair from public;
create table if not exists seo_repair.stage_meta (k text primary key, v text, at timestamptz not null default now());
create table if not exists seo_repair.stage_file (name text primary key, sha256 text not null, content text not null);
create table if not exists seo_repair.stage_link_rules (rule_id text primary key, form text, path text, action text,
  old_target text, dest text, exp_present int, exp_ins int, exp_change int, tol int, pat_ctx text, repl_ctx text,
  pat_md text, pat_html text);
create table if not exists seo_repair.stage_fee_rules (rule_id text primary key, t text, rid text, slug text, col text,
  ord int, category text, old_text text, old_md5 text, new_text text, pin text);
create table if not exists seo_repair.stage_pins (t text, rid text, col text, md5 text, primary key (t, rid, col));

create or replace function seo_repair.run(p_name text) returns text language plpgsql as $f$
declare v text; v_sha text;
begin
  select content, sha256 into v, v_sha from seo_repair.stage_file where name = p_name;
  if v is null then
    raise exception 'seo_repair.run: no staged script %', p_name;
  end if;
  if encode(sha256(convert_to(v, 'UTF8')), 'hex') <> v_sha then
    raise exception 'seo_repair.run: staged script % does not match its sha256', p_name;
  end if;
  execute v;
  return p_name || ': done';
end
$f$;

create or replace function seo_repair.q(p_name text) returns setof jsonb language plpgsql as $f$
declare v text; v_sha text;
begin
  select content, sha256 into v, v_sha from seo_repair.stage_file where name = p_name;
  if v is null then
    raise exception 'seo_repair.q: no staged query %', p_name;
  end if;
  if encode(sha256(convert_to(v, 'UTF8')), 'hex') <> v_sha then
    raise exception 'seo_repair.q: staged query % does not match its sha256', p_name;
  end if;
  return query execute 'select to_jsonb(x) from (' || v || ') x';
end
$f$;

-- nobody but the owner (the role running this) can use the schema, its tables or its functions
alter table seo_repair.stage_meta enable row level security;
alter table seo_repair.stage_file enable row level security;
alter table seo_repair.stage_link_rules enable row level security;
alter table seo_repair.stage_fee_rules enable row level security;
alter table seo_repair.stage_pins enable row level security;
revoke all on all tables in schema seo_repair from public;
revoke all on function seo_repair.run(text), seo_repair.q(text) from public;
do $g$
declare r text;
begin
  foreach r in array array['anon', 'authenticated', 'service_role'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke all on schema seo_repair from %I', r);
      execute format('revoke all on all tables in schema seo_repair from %I', r);
      execute format('revoke all on all sequences in schema seo_repair from %I', r);
      execute format('revoke all on all functions in schema seo_repair from %I', r);
    end if;
  end loop;
end
$g$;

do $ld$
declare
  v_body text;
  b      jsonb;
  v_sha  text;
  v_bad  text;
begin
  select r.content into v_body from net._http_response r
  where r.id = (select v::bigint from seo_repair.stage_meta where k = 'bundle_request') and r.status_code = 200;
  v_sha := encode(sha256(convert_to(v_body, 'UTF8')), 'hex');
  if v_body is null or v_sha is distinct from (select v from seo_repair.stage_meta where k = 'bundle_sha256') then
    raise exception 'seo_repair loader: the fetched bundle is missing or its sha256 is not the expected one';
  end if;
  b := v_body::jsonb;
  if b ->> 'format' is distinct from 'seo-repair-dbtool-1' then
    raise exception 'seo_repair loader: unknown bundle format %', b ->> 'format';
  end if;
  if exists (select 1 from seo_repair.stage_pins) then
    raise exception 'seo_repair loader: pins were already read for the staged rules (%). Loading another bundle would detach them; delete from seo_repair.stage_pins first if a new pin read, dry run and review are intended',
      (select v from seo_repair.stage_meta where k = 'pin_set_sha256');
  end if;
  delete from seo_repair.stage_link_rules;
  delete from seo_repair.stage_fee_rules;
  delete from seo_repair.stage_file;
  insert into seo_repair.stage_link_rules (rule_id, form, path, action, old_target, dest, exp_present, exp_ins, exp_change, tol, pat_ctx, repl_ctx, pat_md, pat_html)
  select rule_id, form, path, action, old_target, dest, exp_present, exp_ins, exp_change, tol, pat_ctx, repl_ctx, pat_md, pat_html from jsonb_to_recordset(b -> 'link_rules') as x(rule_id text, form text, path text, action text, old_target text, dest text, exp_present int, exp_ins int, exp_change int, tol int, pat_ctx text, repl_ctx text, pat_md text, pat_html text);
  insert into seo_repair.stage_fee_rules (rule_id, t, rid, slug, col, ord, category, old_text, old_md5, new_text)
  select rule_id, t, rid, slug, col, ord, category, old_text, old_md5, new_text from jsonb_to_recordset(b -> 'fee_rules') as x(rule_id text, t text, rid text, slug text, col text, ord int, category text, old_text text, old_md5 text, new_text text);
  insert into seo_repair.stage_file (name, sha256, content)
  select f.key, encode(sha256(convert_to(f.value #>> '{}', 'UTF8')), 'hex'), f.value #>> '{}'
  from jsonb_each(b -> 'files') f;
  -- every staged script is byte-identical to the one the bundle lists
  select string_agg(f.name, ', ') into v_bad
  from seo_repair.stage_file f
  where f.sha256 is distinct from (b -> 'file_sha256' ->> f.name);
  if v_bad is not null or (select count(*) from seo_repair.stage_file) <> (select count(*) from jsonb_object_keys(b -> 'file_sha256')) then
    raise exception 'seo_repair loader: staged scripts differ from the bundle manifest: %', coalesce(v_bad, 'count');
  end if;
  -- the staged rules are exactly the generator's rules (field by field, length-prefixed)
  if (select coalesce(encode(sha256(convert_to(string_agg(concat_ws('|', case when rule_id is null then '~' else length(rule_id::text)::text || ':' || rule_id::text end, case when form is null then '~' else length(form::text)::text || ':' || form::text end, case when path is null then '~' else length(path::text)::text || ':' || path::text end, case when action is null then '~' else length(action::text)::text || ':' || action::text end, case when old_target is null then '~' else length(old_target::text)::text || ':' || old_target::text end, case when dest is null then '~' else length(dest::text)::text || ':' || dest::text end, case when exp_present is null then '~' else length(exp_present::text)::text || ':' || exp_present::text end, case when exp_ins is null then '~' else length(exp_ins::text)::text || ':' || exp_ins::text end, case when exp_change is null then '~' else length(exp_change::text)::text || ':' || exp_change::text end, case when tol is null then '~' else length(tol::text)::text || ':' || tol::text end, case when pat_ctx is null then '~' else length(pat_ctx::text)::text || ':' || pat_ctx::text end, case when repl_ctx is null then '~' else length(repl_ctx::text)::text || ':' || repl_ctx::text end, case when pat_md is null then '~' else length(pat_md::text)::text || ':' || pat_md::text end, case when pat_html is null then '~' else length(pat_html::text)::text || ':' || pat_html::text end) || E'\n', '' order by rule_id collate "C"), 'UTF8')), 'hex'), encode(sha256(''::bytea), 'hex')) from seo_repair.stage_link_rules) <> 'ea56d812b647b1809f19940515ff6c2c24c95cbe0ad57d4413c62d55750cd4e5' then
    raise exception 'seo_repair loader: staged link rules digest differs from the generator''s';
  end if;
  if (select coalesce(encode(sha256(convert_to(string_agg(concat_ws('|', case when rule_id is null then '~' else length(rule_id::text)::text || ':' || rule_id::text end, case when t is null then '~' else length(t::text)::text || ':' || t::text end, case when rid is null then '~' else length(rid::text)::text || ':' || rid::text end, case when slug is null then '~' else length(slug::text)::text || ':' || slug::text end, case when col is null then '~' else length(col::text)::text || ':' || col::text end, case when ord is null then '~' else length(ord::text)::text || ':' || ord::text end, case when category is null then '~' else length(category::text)::text || ':' || category::text end, case when old_text is null then '~' else length(old_text::text)::text || ':' || old_text::text end, case when old_md5 is null then '~' else length(old_md5::text)::text || ':' || old_md5::text end, case when new_text is null then '~' else length(new_text::text)::text || ':' || new_text::text end) || E'\n', '' order by rule_id collate "C"), 'UTF8')), 'hex'), encode(sha256(''::bytea), 'hex')) from seo_repair.stage_fee_rules) <> '4cca7d1a3f3164326eccd218318e54e73388ba80353aa91857f9abc2a3bb9cb3' then
    raise exception 'seo_repair loader: staged fee rules digest differs from the generator''s';
  end if;
  insert into seo_repair.stage_meta (k, v) values
    ('bundle_loaded', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')),
    ('bundle_inputs', (b -> 'inputs')::text),
    ('staged_link_rules', (select count(*) from seo_repair.stage_link_rules)::text),
    ('staged_fee_rules', (select count(*) from seo_repair.stage_fee_rules)::text),
    ('staged_rules_digest', 'ea56d812b647b1809f19940515ff6c2c24c95cbe0ad57d4413c62d55750cd4e5 / 4cca7d1a3f3164326eccd218318e54e73388ba80353aa91857f9abc2a3bb9cb3')
  on conflict (k) do update set v = excluded.v, at = now();
end
$ld$;

files.pins.sql:
do $p0$
begin
  if exists (select 1 from seo_repair.stage_pins) then
    raise exception 'seo_repair pins: pins were already read (pin set %). A new pin read is a new dry run and a new review; delete from seo_repair.stage_pins first if that is intended',
      (select v from seo_repair.stage_meta where k = 'pin_set_sha256');
  end if;
  if not exists (select 1 from seo_repair.stage_link_rules) and not exists (select 1 from seo_repair.stage_fee_rules) then
    raise exception 'seo_repair pins: no staged rules';
  end if;
end
$p0$;
create temp table _seo_link_rules on commit drop as select * from seo_repair.stage_link_rules;
insert into seo_repair.stage_pins (t, rid, col, md5)
select distinct k.t, k.rid, k.col, md5(k.val)
from (
  select f.t, f.rid, f.slug, f.col, f.val, n.form, n.path
  from (
    select $seo$content_pages$seo$::text as t, x.id::text as rid, x.slug, $seo$content$seo$::text as col, x.content as val
    from public.content_pages x where x.content ~* $seo$poolrentalnearme|\]\(\s*<?/|href$seo$
    union all
    select $seo$content_pages$seo$::text as t, x.id::text as rid, x.slug, $seo$body_markdown$seo$::text as col, x.body_markdown as val
    from public.content_pages x where x.body_markdown ~* $seo$poolrentalnearme|\]\(\s*<?/|href$seo$
    union all
    select $seo$blog_posts$seo$::text as t, x.id::text as rid, x.slug, $seo$content$seo$::text as col, x.content as val
    from public.blog_posts x where x.content ~* $seo$poolrentalnearme|\]\(\s*<?/|href$seo$
  ) f
  cross join lateral (
    select distinct
      case when m[1] ~* '^https?://poolrentalnearme\.com' then 'n' else 'w' end as form,
      coalesce(nullif(regexp_replace(split_part(split_part(
        regexp_replace(m[1], '^https?://(www\.)?poolrentalnearme\.com', '', 'i'), '#', 1), '?', 1), '/+$', ''), ''), '/') as path
    from regexp_matches(f.val, $seo$(?:\]\(\s*<?|[Hh][Rr][Ee][Ff]\s*=\s*\\?["'])([^)\s"'<>\\]+)$seo$, 'g') m
    where m[1] ~* '^https?://(www\.)?poolrentalnearme\.com' or (m[1] ~ '^/' and m[1] !~ '^//')
  ) n
) k
join _seo_link_rules r on r.form = k.form and r.path = k.path;
insert into seo_repair.stage_pins (t, rid, col, md5)
select f.t, f.rid, f.col, coalesce(md5(case f.t when $seo$content_pages$seo$ then (select (case f.col when $seo$body_markdown$seo$ then x.body_markdown when $seo$content$seo$ then x.content when $seo$description$seo$ then x.description when $seo$og_description$seo$ then x.og_description when $seo$seo_description$seo$ then x.seo_description when $seo$seo_title$seo$ then x.seo_title end)::text from public.content_pages x where x.id = f.rid::uuid) end), 'MISSING')
from (select distinct t, rid, col from seo_repair.stage_fee_rules) f
on conflict (t, rid, col) do nothing;
update seo_repair.stage_fee_rules r set pin = p.md5
from seo_repair.stage_pins p where p.t = r.t and p.rid = r.rid and p.col = r.col;
do $p1$
begin
  if exists (select 1 from seo_repair.stage_fee_rules where pin is null) then
    raise exception 'seo_repair pins: a fee rule has no pin';
  end if;
end
$p1$;
insert into seo_repair.stage_meta (k, v) values
  ('pin_set_sha256', (select coalesce(encode(sha256(convert_to(string_agg(t || E'\t' || rid || E'\t' || col || E'\t' || md5 || E'\n', '' order by t collate "C", rid collate "C", col collate "C"), 'UTF8')), 'hex'), encode(sha256(''::bytea), 'hex')) from seo_repair.stage_pins)),
  ('pinned_fields', (select count(*) from seo_repair.stage_pins)::text),
  ('pinned_at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'))
on conflict (k) do update set v = excluded.v, at = now();

files.rollback.sql:
set local statement_timeout = '60min';
set local lock_timeout = '15s';

create table if not exists seo_repair.seo_repair_rollback_log (
  id           bigserial primary key,
  rollback_run text not null,
  table_name   text not null,
  row_id       text not null,
  slug         text,
  column_name  text not null,
  status       text not null,
  reason       text,
  logged_at    timestamptz not null default now()
);
alter table seo_repair.seo_repair_rollback_log enable row level security;
do $rbgrants$
declare r text;
begin
  foreach r in array array['anon', 'authenticated'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke all on seo_repair.seo_repair_rollback_log from %I', r);
    end if;
  end loop;
end
$rbgrants$;

create temp table _seo_rb_run on commit drop as
select 'rollback-' || to_char(now() at time zone 'utc', 'YYYYMMDD"T"HH24MISS"Z"') || '-' || txid_current()::text as run_id,
       (select nullif(v, '') from seo_repair.stage_meta where k = 'rollback_only_run') as only_run;

do $rb$
declare
  v_run   text := (select run_id from _seo_rb_run);
  v_only  text := (select only_run from _seo_rb_run);
  f       record;
  e       record;
  v_first text;
  v_last  text;
  v_slug  text;
  v_ok    boolean;
  v_why   text;
  v_val   text;
  v_bak   text;
  v_rows  int;
  v_rest  int := 0;
  v_skip  int := 0;
begin
  if to_regclass('seo_repair.seo_repair_change_log') is null or to_regclass('seo_repair.seo_repair_backup_20261115') is null then
    raise notice 'SEO repair rollback: no change log or backup table (apply never committed); nothing to roll back';
    return;
  end if;
  if v_only is not null and not exists (select 1 from seo_repair.seo_repair_change_log where run_id = v_only) then
    raise notice 'SEO repair rollback: run % has no logged changes; nothing to roll back', v_only;
  end if;
  for f in
    select distinct table_name, row_id, column_name
    from seo_repair.seo_repair_change_log where rolled_back_at is null and (v_only is null or run_id = v_only)
    order by 1, 2, 3
  loop
    v_first := null; v_last := null; v_ok := true; v_why := null; v_slug := null;
    for e in
      select * from seo_repair.seo_repair_change_log
      where table_name = f.table_name and row_id = f.row_id and column_name = f.column_name and rolled_back_at is null
        and (v_only is null or run_id = v_only)
      order by id
    loop
      if v_first is null then
        v_first := e.old_md5;
      elsif e.old_md5 <> v_last then
        v_ok := false;
        v_why := 'change chain broken: the field was edited between two logged changes; restore by hand from the backup table';
      end if;
      v_last := e.new_md5;
      v_slug := coalesce(e.slug, v_slug);
    end loop;

    execute format('select %I from public.%I where id = $1::uuid for update', f.column_name, f.table_name)
      into v_val using f.row_id;
    get diagnostics v_rows = row_count;  -- EXECUTE does not set FOUND
    if v_rows = 0 then
      v_ok := false; v_why := 'row no longer exists';
    elsif v_ok and md5(v_val) is distinct from v_last then
      v_ok := false; v_why := 'field was edited after apply, or a later run changed it (current md5 differs from the md5 this run wrote); left as is';
    end if;
    if v_ok then
      select old_value into v_bak from seo_repair.seo_repair_backup_20261115
      where table_name = f.table_name and row_id = f.row_id and column_name = f.column_name and old_md5 = v_first;
      if not found then
        v_ok := false; v_why := 'no backup row with the md5 of the value before the first change';
      end if;
    end if;

    if v_ok then
      execute format('update public.%I set %I = $1 where id = $2::uuid and md5(%I) = $3',
                     f.table_name, f.column_name, f.column_name)
        using v_bak, f.row_id, v_last;
      get diagnostics v_rows = row_count;
      if v_rows <> 1 then
        raise exception 'SEO repair rollback: guarded restore of %.% id % touched % rows; aborting',
          f.table_name, f.column_name, f.row_id, v_rows;
      end if;
      update seo_repair.seo_repair_change_log set rolled_back_at = now()
      where table_name = f.table_name and row_id = f.row_id and column_name = f.column_name and rolled_back_at is null
        and (v_only is null or run_id = v_only);
      insert into seo_repair.seo_repair_rollback_log (rollback_run, table_name, row_id, slug, column_name, status)
      values (v_run, f.table_name, f.row_id, v_slug, f.column_name, 'restored');
      v_rest := v_rest + 1;
    else
      insert into seo_repair.seo_repair_rollback_log (rollback_run, table_name, row_id, slug, column_name, status, reason)
      values (v_run, f.table_name, f.row_id, v_slug, f.column_name, 'skipped', v_why);
      v_skip := v_skip + 1;
    end if;
  end loop;
  raise notice 'SEO repair rollback %: % field(s) restored, % skipped', v_run, v_rest, v_skip;
end
$rb$;
insert into seo_repair.stage_meta (k, v) values ('last_rollback_run', (select run_id from _seo_rb_run))
on conflict (k) do update set v = excluded.v, at = now();

files.rollback_summary.sql:
select status, count(*) as fields
from seo_repair.seo_repair_rollback_log where rollback_run = (select v from seo_repair.stage_meta where k = 'last_rollback_run')
group by status order by status
